function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 500) return 'n is an integer from 1 to 500.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 10000) return 'queries needs 1 to 10000 entries.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 4 || q.some(v => !Number.isInteger(v))) return 'Each query is four integers [row1, col1, row2, col2].';
    const [row1, col1, row2, col2] = q;
    if (row1 < 0 || row1 > row2 || row2 >= n) return 'Each query needs 0 <= row1 <= row2 < n.';
    if (col1 < 0 || col1 > col2 || col2 >= n) return 'Each query needs 0 <= col1 <= col2 < n.';
  }
  return null;
}

