function rangeAddQueries(n, queries) {
  const diff = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
  for (const [row1, col1, row2, col2] of queries) {
    diff[row1][col1] += 1;
    diff[row1][col2 + 1] -= 1;
    diff[row2 + 1][col1] -= 1;
    diff[row2 + 1][col2 + 1] += 1;
  }

  const mat = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const above = row > 0 ? mat[row - 1][col] : 0;
      const left = col > 0 ? mat[row][col - 1] : 0;
      const corner = row > 0 && col > 0 ? mat[row - 1][col - 1] : 0;
      mat[row][col] = diff[row][col] + above + left - corner;
    }
  }
  return mat;
}

