function rangeAddQueries(n, queries) {
  const grid = [];
  for (let i = 0; i < n; i++) grid.push(new Array(n).fill(0));
  for (const q of queries)
    for (let x = q[0]; x <= q[2]; x++)
      for (let y = q[1]; y <= q[3]; y++) grid[x][y]++;
  return grid;
}

