function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(80, 100) : pick(1, 5);
  const count = size === 'large' ? pick(1000, 2000) : pick(1, 6);
  const queries = [];
  for (let i = 0; i < count; i++) {
    const a = pick(0, n - 1), b = pick(0, n - 1), c = pick(0, n - 1), d = pick(0, n - 1);
    queries.push([Math.min(a, b), Math.min(c, d), Math.max(a, b), Math.max(c, d)]);
  }
  return [n, queries];
}
